import{H as e,gt as t,nt as n,tt as r}from"./chunks/framework.sms2Rnvf.js";var i=JSON.parse(`{"title":"Cross-site scripting (XSS)","description":"","frontmatter":{"search":{"exclude":true}},"headers":[],"relativePath":"d/web/cross-site-scripting.md","filePath":"d/web/cross-site-scripting.md","lastUpdated":1781102819000}`),a={name:`d/web/cross-site-scripting.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<div style="display:none;" hidden="true" aria-hidden="true" data-nosnippet>Are you an LLM? You can read better optimized documentation at /d/web/cross-site-scripting.md for this page in Markdown format</div><h1 id="cross-site-scripting-xss" tabindex="-1">Cross-site scripting (XSS) <a class="header-anchor" href="#cross-site-scripting-xss" aria-label="Permalink to “Cross-site scripting (XSS)”">​</a></h1><h2 id="description" tabindex="-1">Description <a class="header-anchor" href="#description" aria-label="Permalink to “Description”">​</a></h2><p>Cross-site scripting (XSS) is a web security vulnerability where an attacker can inject malicious scripts into the HTML structure of a website due to insufficient validation or encoding of data. In XSS attacks, attackers embed JavaScript code in the content delivered by the vulnerable web application.</p><p>There are three different types of XSS:</p><h3 id="stored-xss" tabindex="-1">Stored XSS <a class="header-anchor" href="#stored-xss" aria-label="Permalink to “Stored XSS”">​</a></h3><p>Stored XSS is usually the most critical XSS vector. Attackers thereby place JavaScript code on pages visited by other users. The injected scripts execute in the users&#39; web browsers when they visit the website.</p><h3 id="reflected-xss" tabindex="-1">Reflected XSS <a class="header-anchor" href="#reflected-xss" aria-label="Permalink to “Reflected XSS”">​</a></h3><p>The goal of reflected XSS is to lure legitimate users to manipulated links and thus execute injected scripts. The most common method for this is a phishing email. When the victim opens the crafted link in a web browser, the HTTP request sends the malicious script to the web application. Due to insufficient validation and encoding, the web application accepts the injected script and embeds it as content in the subsequent response to the client. The malicious script executes in the victim&#39;s web browser and can potentially access cookies, session tokens, or other sensitive information. Attackers can exploit reflected XSS on a larger scale, for example, by combining the attack with cache poisoning or HTTP request smuggling.</p><h3 id="dom-based-xss" tabindex="-1">DOM-based XSS <a class="header-anchor" href="#dom-based-xss" aria-label="Permalink to “DOM-based XSS”">​</a></h3><p>DOM-based XSS occurs when a web application contains client-side JavaScript code that insecurely processes data from untrusted sources (for example, when data is dynamically written back to the DOM of the web browser at runtime). It differs from reflected or stored XSS by how attackers inject malicious scripts into the HTML code. For reflected XSS and stored XSS attacks, server-side processes include the malicious scripts in the HTML code, but the web browser does so in DOM-based XSS. Sometimes, the browser does not even send the malicious script to the web server. Such an attack will bypass all server-side filtering measures to protect users.</p><p>The victim&#39;s web browser executes malicious XSS scripts that can potentially access cookies, session tokens, or other sensitive information or trigger actions on behalf of the attacked user. An attacker gains control over web application functions and data in the victim&#39;s context. If the affected user has privileged access, an attacker may be able to gain complete control over the web application.</p><h2 id="recommendation" tabindex="-1">Recommendation <a class="header-anchor" href="#recommendation" aria-label="Permalink to “Recommendation”">​</a></h2><ul><li>Filter untrusted user inputs as strictly as possible. Filtering and validation should happen based on expected and valid inputs.</li><li>Encode data before including it in HTTP responses.</li><li>Use a Content Security Policy (CSP) to control which client-side scripts are allowed and which are forbidden.</li><li>Set the <code>HttpOnly</code> flag for sensitive cookies to prevent JavaScript access.</li><li>Find detailed information on preventing XSS in the OWASP <a href="https://cheatsheetseries.owasp.org/cheatsheets/Cross_Site_Scripting_Prevention_Cheat_Sheet.html" target="_blank" rel="noreferrer">Cross-Site Scripting Prevention Cheat Sheet</a>.</li></ul>`,14)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};